import React, { useState, useEffect, useContext } from "react";
import axios from "../utils/axiosInstance";
import GeneralContext from "./GeneralContext";

const Search = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const { refreshAll } = useContext(GeneralContext); // For reloading watchlist after adding

  const handleChange = async (e) => {
    const input = e.target.value.toUpperCase();
    setQuery(input);

    if (input.length < 2) {
      setResults([]);
      return;
    }

    const possibleExchanges = [".NS", ".BO"]; // NSE & BSE suffixes
    const candidates = possibleExchanges.map((ex) => `${input}${ex}`);

    const tempResults = [];

    for (let symbol of candidates) {
      try {
        const res = await axios.get(`/price/${symbol}`);
        if (res.data.price) {
          tempResults.push({
            symbol: res.data.symbol,
            price: res.data.price,
            exchange: symbol.endsWith(".NS") ? "NSE" : "BSE",
          });
        }
      } catch (err) {
        // silently ignore
      }
    }

    setResults(tempResults);
  };

  const handleAdd = async (symbol) => {
    try {
      await axios.post("/api/watchlist", { symbol });
      setQuery("");
      setResults([]);
      refreshAll(); // refresh frontend watchlist
    } catch (err) {
      console.error("Error adding to watchlist:", err.message);
    }
  };

  return (
    <div className="search-container">
      <input
        type="text"
        value={query}
        onChange={handleChange}
        placeholder="Search eg: INFY, SBIN, RELIANCE"
        className="search"
      />
      {results.length > 0 && (
        <ul className="search-results">
          {results.map((stock, idx) => (
            <li key={idx} onClick={() => handleAdd(stock.symbol)}>
              {stock.symbol} — ₹{stock.price} ({stock.exchange})
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Search;
